function makeProbe(enemy=false){const g=new THREE.Group(),bright=new THREE.MeshStandardMaterial({color:enemy?0xd75a41:0x55dbdf,emissive:enemy?0xfc4d25:0x29cad7,emissiveIntensity:2,metalness:.3,roughness:.4});const body=new THREE.Mesh(bodyGeo,enemy?darkMetal:metal);body.rotation.x=Math.PI/2;g.add(body);const nose=new THREE.Mesh(noseGeo,metal);nose.rotation.x=-Math.PI/2;nose.position.z=-7.4;g.add(nose);for(const z of [-3,3.5]){const ring=new THREE.Mesh(ringGeo,bright);ring.position.z=z;g.add(ring);}for(const x of [-10,10]){const fin=new THREE.Mesh(finGeo,panelMat);fin.position.set(x,0,1);g.add(fin);for(let i=0;i<5;i++){const rib=new THREE.Mesh(new THREE.BoxGeometry(.17,.33,5),metal);rib.position.set(x-5+i*2.5,0,1);g.add(rib);}}const strut=new THREE.Mesh(strutGeo,metal);strut.position.z=1;g.add(strut);const antenna=new THREE.Mesh(new THREE.CylinderGeometry(.12,.12,6,6),metal);antenna.position.set(0,4,-2);g.add(antenna);const dish=new THREE.Mesh(new THREE.SphereGeometry(1.5,16,8,0,Math.PI*2,0,.9),metal);dish.position.set(0,6.8,-2);dish.rotation.z=Math.PI;g.add(dish);for(const x of [-1.35,1.35]){const engine=new THREE.Mesh(engineGeo,darkMetal);engine.rotation.x=Math.PI/2;engine.position.set(x,0,7);g.add(engine);const glow=new THREE.Sprite(new THREE.SpriteMaterial({map:glowTexture,color:enemy?0xff5c33:0x4bd9ff,blending:THREE.AdditiveBlending,depthWrite:false}));glow.position.set(x,0,8.6);glow.scale.set(7,7,1);g.add(glow);}if(enemy){g.scale.setScalar(1.2);for(const x of [-5,5]){const blade=new THREE.Mesh(new THREE.ConeGeometry(2,12,3),new THREE.MeshStandardMaterial({color:0x5e2d2b,metalness:.7,roughness:.4}));blade.rotation.x=-Math.PI/2;blade.position.set(x,0,-2);g.add(blade);}}if(!enemy)g.scale.setScalar(.65);return g;}
