function toggleMute(){muted=!muted;$('mute').textContent=muted?'Sound off':'Sound on';}
function reset(name){if(game){for(const mesh of shipMeshes.values())scene.remove(mesh);for(const mesh of missileMeshes.values())scene.remove(mesh);shipMeshes.clear();missileMeshes.clear();for(const p of plates.values())p.el.remove();plates.clear();for(const e of effects){scene.remove(e.mesh);e.geo.dispose();e.mat.dispose();}effects.length=0;}game=new Game(name);if(touchMode)game.yaw=-.18;window.__game=game;started=true;first=true;camera.position.set(0,14,65);$('boot').hidden=true;$('hud').hidden=false;$('gameover').hidden=true;$('pause-title').textContent='Welcome to deep space.';$('pause-copy').textContent='You are a mind in a machine. Explore, replicate, and keep your fleet alive.';$('pause-eyebrow').textContent='CONSCIOUSNESS ONLINE';$('resume').textContent='Begin flight';setPause(true);updateHUD();}
$('identity').addEventListener('submit',e=>{e.preventDefault();const name=$('name').value.trim();$('name').blur();if(!name){$('name').focus();return;}if(!audio){try{audio=new (window.AudioContext||window.webkitAudioContext)();}catch{}}reset(name);});$('resume').onclick=()=>setPause(false);$('pause-button').onclick=()=>setPause(true);$('mute').onclick=toggleMute;$('restart').onclick=()=>reset(game.name);canvas.addEventListener('click',()=>{if(game&&!game.paused&&!game.over)lockPointer();});
window.addEventListener('keydown',e=>{if(!started)return;const code=e.code;if(['Space','Tab','ControlLeft','ControlRight','KeyW','KeyA','KeyS','KeyD','Digit1','Digit2','Escape'].includes(code))e.preventDefault();if(code==='Escape'){if(!e.repeat)setPause(!game.paused);return;}if(game.paused||game.over)return;keys.add(code);if(!e.repeat){if(code==='Digit1')game.fire('missile');if(code==='Digit2')game.fire('rail');if(code==='KeyF'){game.warp=!game.warp;game.autopilot=false;toast(game.warp?'Warp drive online · safety limiter active':'Sublight thrusters online');}if(code==='KeyG'){game.autopilot=!game.autopilot;toast(game.autopilot?`Navigating to ${game.planets[game.targetPlanet].name} · movement cancels`:'Navigation disengaged');}if(code==='KeyN')game.cycleDestination();if(code==='Tab')game.switchShip();if(code==='KeyM')toggleMute();}});window.addEventListener('keyup',e=>{keys.delete(e.code);if(e.code==='KeyC'&&game){game.cloneLatch=false;game.cloneProgress=0;}});window.addEventListener('blur',()=>{if(game&&!game.paused&&!game.over)setPause(true);});document.addEventListener('visibilitychange',()=>{if(document.hidden&&game&&!game.paused&&!game.over)setPause(true);});document.addEventListener('pointerlockchange',()=>{if(document.pointerLockElement===canvas)ignoreMouse=true;if(started&&!document.pointerLockElement&&!game.paused&&!game.over)setPause(true);});
let lastMouse={x:null,y:null};window.addEventListener('mousemove',e=>{if(touchMode)return;if(!game||game.paused||game.over){lastMouse.x=e.clientX;lastMouse.y=e.clientY;return;}if(ignoreMouse){ignoreMouse=false;lastMouse={x:e.clientX,y:e.clientY};return;}let dx=e.movementX,dy=e.movementY;if(document.pointerLockElement!==canvas){dx=lastMouse.x===null?0:e.clientX-lastMouse.x;dy=lastMouse.y===null?0:e.clientY-lastMouse.y;}lastMouse={x:e.clientX,y:e.clientY};if(!game.autopilot){game.yaw+=clamp(dx,-100,100)*.0025;game.pitch=clamp(game.pitch-clamp(dy,-100,100)*.0025,-1.45,1.45);}});
function render(now){requestAnimationFrame(render);const dt=Math.min((now-last)/1000,.05);last=now;if(!started)return;const input={w:keys.has('KeyW'),s:keys.has('KeyS'),a:keys.has('KeyA'),d:keys.has('KeyD'),up:keys.has('Space'),down:keys.has('ControlLeft')||keys.has('ControlRight'),boost:keys.has('ShiftLeft')||keys.has('ShiftRight'),brake:keys.has('KeyX'),c:keys.has('KeyC'),one:keys.has('Digit1'),two:keys.has('Digit2')};const touchInput=touch.frame(dt);input.strafe=touchInput.strafe||0;input.throttle=touchInput.throttle||0;for(const key of ['up','down','boost','brake','c','one','two'])input[key]=input[key]||touchInput[key];game.step(dt,input);handleEvents();if(!game.paused&&!game.over)updateEffects(dt);const dir=new THREE.Vector3(...game.forward());const desired=dir.clone().multiplyScalar(-65);desired.y+=14;camera.position.lerp(desired,1-Math.exp(-dt*7));camera.lookAt(dir.clone().multiplyScalar(500));camera.updateMatrixWorld();worldRefresh-=dt;if(worldRefresh<=0){worldRefresh=.5;distantWorlds=new Set([...game.planets].sort((a,b)=>dist(a.pos,game.leader.pos)-dist(b.pos,game.leader.pos)).slice(0,24).map(p=>p.id));}for(const p of game.planets){const mesh=planetMeshes.get(p.id),distance=dist(p.pos,game.leader.pos);mesh.visible=distance<8000+p.radius||distantWorlds.has(p.id)||p.id===game.targetPlanet;if(mesh.visible){mesh.position.fromArray(sub(p.pos,game.leader.pos));if(!game.paused&&p.id===0)mesh.children[0].rotation.y+=dt*.003;}}syncShips();syncMissiles();$('replicate').style.opacity=game.cloneProgress>0?1:0;$('clone-fill').style.width=`${game.cloneProgress/1.2*100}%`;if(now>toastUntil)$('toast').style.opacity=0;hudTimer-=dt;if(hudTimer<=0){hudTimer=.1;updateHUD();}renderer.render(scene,camera);}
function resizeView(){camera.aspect=innerWidth/innerHeight;camera.fov=touchMode&&innerWidth<innerHeight?78:58;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);}window.addEventListener('resize',resizeView);window.visualViewport?.addEventListener('resize',resizeView);
const touch=new TouchControls({isPlaying:()=>!!game&&!game.paused&&!game.over,onAim:(yaw,pitch)=>{if(game&&!game.autopilot){game.yaw+=yaw;game.pitch=clamp(game.pitch+pitch,-1.45,1.45);}},onAction:action=>{if(!game)return;if(action==='releaseClone'){game.cloneLatch=false;game.cloneProgress=0;return;}if(game.paused||game.over)return;if(action==='missile'||action==='rail')game.fire(action);if(action==='warp'){game.warp=!game.warp;game.autopilot=false;toast(game.warp?'Warp drive online':'Sublight thrusters online');}if(action==='navigate'){game.autopilot=!game.autopilot;toast(game.autopilot?'Navigating to '+game.planets[game.targetPlanet].name:'Navigation disengaged');}if(action==='next')game.cycleDestination();if(action==='switch')game.switchShip();}});
function setMode(value){touchMode=value;touch.setEnabled(value);$('mode-desktop').setAttribute('aria-pressed',String(!value));$('mode-touch').setAttribute('aria-pressed',String(value));$('touch-guide').hidden=!value;$('input-mode-pause').textContent=value?'Use keyboard controls':'Use touch controls';$('load').textContent=$('start').disabled?'Preparing universe…':value?'Touch controls · portrait or landscape':'Desktop · mouse & keyboard';$('pause-button').innerHTML=value?'Pause':'Controls <kbd>ESC</kbd>';renderer.setPixelRatio(Math.min(devicePixelRatio,value?1.35:1.8));resizeView();if(value&&document.pointerLockElement)document.exitPointerLock?.();}
$('mode-desktop').onclick=()=>setMode(false);$('mode-touch').onclick=()=>setMode(true);$('input-mode-pause').onclick=()=>setMode(!touchMode);setMode(touchMode);window.__touch=touch;
makeStars();new THREE.TextureLoader().load('./assets/earth.jpg',texture=>{texture.colorSpace=THREE.SRGBColorSpace;texture.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());const planets=new Game().planets;for(const p of planets)addPlanet(p,texture);$('start').disabled=false;setMode(touchMode);requestAnimationFrame(render);},undefined,()=>{$('load').textContent='Earth texture could not load. Reload to try again.';});
window.__render={renderer,scene,camera,planetMeshes,shipMeshes};
